import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val a = st.nextToken().toLong()
    val b = st.nextToken().toLong()
    val c = st.nextToken().toLong()

    // x = bonds between 1 and 2
    // y = bonds between 2 and 3
    // z = bonds between 3 and 1
    // System:
    // x + z = a
    // x + y = b
    // y + z = c
    //
    // Solve:
    // x = (a + b - c) / 2
    // y = (b + c - a) / 2
    // z = (c + a - b) / 2

    val xNum = a + b - c
    val yNum = b + c - a
    val zNum = c + a - b

    // Check parity and non-negativity
    if (xNum < 0 || yNum < 0 || zNum < 0 ||
        xNum % 2L != 0L || yNum % 2L != 0L || zNum % 2L != 0L
    ) {
        println("Impossible")
        return
    }

    val x = xNum / 2
    val y = yNum / 2
    val z = zNum / 2

    // Ensure no atom has zero bonds (each valence >=1 already, but check)
    if (x + z != a || x + y != b || y + z != c) {
        println("Impossible")
        return
    }

    println("$x $y $z")
}

